  const cGradA = new Color(stops[0]?.hex ?? '#0b0b10');
  const cGradB = new Color(stops[stops.length - 1]?.hex ?? '#16161d');

  const tier = ctx.tier || 'T1';
  const totalCount = tier === 'T0' ? 600 : 1200;
  const coreCount = Math.max(24, Math.round((totalCount * 90) / 1200));
  const fieldCount = totalCount - coreCount;

  // ---------------------------------------------------------------------
  // BACKDROP — engineered vertical gradient, ~7x6 units at z = -2.5
  // ---------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
