    vec3(cGradA.r, cGradA.g, cGradA.b),
    vec3(cGradB.r, cGradB.g, cGradB.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------------------------------------------------------------------
  // STAR FIELD — instanced icosahedra through an ellipsoidal shell
  // ---------------------------------------------------------------------
  const starGroup = new Group();
  starGroup.name = 'star-field';
  group.add(starGroup);

  const ellipsoidAxes = { x: 3, y: 2, z: 2.5 };
  const ellipsoidCenter = { x: 0, y: 0, z: -1.5 };

  function randomEllipsoidPoint() {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const rShell = 0.72 + Math.random() * 0.28;
    const sx = Math.sin(phi) * Math.cos(theta);
    const sy = Math.sin(phi) * Math.sin(theta);
    const sz = Math.cos(phi);
    return {
      x: ellipsoidCenter.x + ellipsoidAxes.x * rShell * sx,
      y: ellipsoidCenter.y + ellipsoidAxes.y * rShell * sy,
      z: ellipsoidCenter.z + ellipsoidAxes.z * rShell * sz,
    };
  }

  function randomSpherePoint(radius) {
