  const fieldMat = new MeshStandardNodeMaterial({
    roughness: 1,
    metalness: 0,
    transparent: true,
    depthWrite: false,
  });
  fieldMat.colorNode = vec3(cPaper.r, cPaper.g, cPaper.b);
  fieldMat.emissiveNode = vec3(cPaper.r, cPaper.g, cPaper.b).mul(0.9);
  fieldMat.opacityNode = attribute('aOpacity', 'float');

  const fieldMesh = new InstancedMesh(particleGeo, fieldMat, fieldCount);
  fieldMesh.name = 'field-particles';
  const fieldBase = new Float32Array(fieldCount * 3);
  const fieldPhase = new Float32Array(fieldCount);
  const fieldOpacity = new Float32Array(fieldCount);
  const mtx = new Matrix4();

  for (let i = 0; i < fieldCount; i++) {
    const p = randomEllipsoidPoint();
    fieldBase[i * 3] = p.x;
    fieldBase[i * 3 + 1] = p.y;
    fieldBase[i * 3 + 2] = p.z;
    fieldPhase[i] = Math.random() * Math.PI * 2;
    fieldOpacity[i] = depthOpacity(p.z);
    mtx.makeTranslation(p.x, p.y, p.z);
    fieldMesh.setMatrixAt(i, mtx);
  }
  particleGeo.setAttribute('aOpacity', new InstancedBufferAttribute(fieldOpacity, 1));
